mapper.update:
UPDATE user_video_record
last_watch_time = #{lastWatchTime}, watch_duration = #{watchDuration}, play_count = #{playCount}, is_finished = #{isFinished}, last_update_time = #{lastUpdateTime},
WHERE id = #{id}

mapper.select:
SELECT id, user_id, video_id, last_watch_time, watch_duration, play_count, is_finished, duration, last_update_time, create_time
FROM user_video_record
WHERE user_id = #{userId} AND video_id = #{videoId}
